module ram_w13x10_r13x10
  (
  clk1,
  ra1,
  wa1,
  wd1,
  we1,
  rd1
  );

  input clk1;
  input [12:0] ra1;
  input [12:0] wa1;
  input [9:0] wd1;
  input we1;
  output [9:0] rd1;

  parameter DATA_DEPTH_LEFT = "0";
  parameter DATA_DEPTH_RIGHT = "0";
  parameter DATA_WIDTH_LEFT = "0";
  parameter DATA_WIDTH_RIGHT = "0";
  parameter RETIMING = 0;
  parameter LOGIC_W = 0;
  parameter SPLITED = 0;
  parameter INIT_VALUE = {81920{1'bx}};
  parameter HAS_INIT = "0";

  reg [9:0] ram [8191:0];

  integer i;
  initial begin
    if(HAS_INIT=="1") begin
      for(i=0; i<8192; i=i+1)
        if(INIT_VALUE==={81920{1'bx}})
          ram[i] <= 10'd0;
        else
          ram[i] <= INIT_VALUE[i*10+:10];
    end
  end

  always @(posedge clk1) begin
    if(we1) begin
      ram[wa1] <= wd1;
    end
  end
  assign rd1 = ram[ra1];


endmodule 

