module ram_w2x16_r2x16_r2x16_r6x1
  (
  clk1,
  ra1,
  ra2,
  ra3,
  wa1,
  wd1,
  we1,
  rd1,
  rd2,
  rd3
  );

  input clk1;
  input [1:0] ra1;
  input [1:0] ra2;
  input [5:0] ra3;
  input [1:0] wa1;
  input [15:0] wd1;
  input we1;
  output [15:0] rd1;
  output [15:0] rd2;
  output rd3;

  parameter DATA_DEPTH_LEFT = "0";
  parameter DATA_DEPTH_RIGHT = "0";
  parameter DATA_WIDTH_LEFT = "0";
  parameter DATA_WIDTH_RIGHT = "0";
  parameter RETIMING = 0;
  parameter LOGIC_W = 0;
  parameter SPLITED = 0;
  parameter INIT_VALUE = {64{1'bx}};
  parameter HAS_INIT = "0";

  reg [15:0] ram [3:0];

  integer i;
  initial begin
    if(HAS_INIT=="1") begin
      for(i=0; i<4; i=i+1)
        if(INIT_VALUE==={64{1'bx}})
          ram[i] <= 16'd0;
        else
          ram[i] <= INIT_VALUE[i*16+:16];
    end
  end

  always @(posedge clk1) begin
    if(we1) begin
      ram[wa1] <= wd1;
    end
  end
