module ram_w2x29_r2x29_r2x29
  (
  clk1,
  ra1,
  ra2,
  wa1,
  wd1,
  we1,
  rd1,
  rd2
  );

  input clk1;
  input [1:0] ra1;
  input [1:0] ra2;
  input [1:0] wa1;
  input [28:0] wd1;
  input we1;
  output [28:0] rd1;
  output [28:0] rd2;

  parameter DATA_DEPTH_LEFT = "0";
  parameter DATA_DEPTH_RIGHT = "0";
  parameter DATA_WIDTH_LEFT = "0";
  parameter DATA_WIDTH_RIGHT = "0";
  parameter RETIMING = 0;
  parameter LOGIC_W = 0;
  parameter SPLITED = 0;
  parameter INIT_VALUE = {116{1'bx}};
  parameter HAS_INIT = "0";

  reg [28:0] ram [3:0];

  integer i;
  initial begin
    if(HAS_INIT=="1") begin
      for(i=0; i<4; i=i+1)
        if(INIT_VALUE==={116{1'bx}})
          ram[i] <= 29'd0;
        else
          ram[i] <= INIT_VALUE[i*29+:29];
    end
  end

  always @(posedge clk1) begin
    if(we1) begin
      ram[wa1] <= wd1;
    end
  end
  assign rd1 = ram[ra1];
  assign rd2 = ram[ra2];


endmodule 

